import{_ as i,o as a,c as t,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"NeoMorphix UIX","description":"Brève présentation du thème Home Assistant « NeoMorphix UIX ».","frontmatter":{"title":"NeoMorphix UIX","description":"Brève présentation du thème Home Assistant « NeoMorphix UIX »."},"headers":[],"relativePath":"fr/collection/neomorphix-uix/index.md","filePath":"fr/collection/neomorphix-uix/index.md","lastUpdated":1793126673000}'),s={name:"fr/collection/neomorphix-uix/index.md"};function o(n,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[r(`<p><a id="orientation-actuelle"></a></p><h1 id="neomorphix-uix" tabindex="-1">NeoMorphix UIX <a class="header-anchor" href="#neomorphix-uix" aria-label="Permalink to &quot;NeoMorphix UIX {#neomorphix-uix}&quot;">​</a></h1><p>NeoMorphix UIX est une variante UIX du thème Home Assistant « NeuMorphix ». Il mise sur des ombres douces, des formes arrondies et un aspect légèrement en relief pour les tableaux de bord.</p><div class="warning custom-block"><p class="custom-block-title">Remarque non officielle</p><p>Cette page ne constitue pas une documentation officielle du projet. Elle résume en français les principales instructions d&#39;installation et d&#39;utilisation. Le dépôt (repository) original demeure la référence.</p></div><table tabindex="0"><thead><tr><th>Champ</th><th>Valeur</th></tr></thead><tbody><tr><td>Projet original</td><td><a href="https://github.com/yakidd/NeumorphixHome" target="_blank" rel="noreferrer">yakidd/NeumorphixHome</a></td></tr><tr><td>Commit vérifié</td><td><a href="https://github.com/yakidd/NeumorphixHome/commit/269c298e47b02faaac4f08c8c9dfccf49d70d860" target="_blank" rel="noreferrer"><code>269c298e47b02faaac4f08c8c9dfccf49d70d860</code></a></td></tr><tr><td>Version</td><td><a href="https://github.com/yakidd/NeumorphixHome/releases/tag/1.0.3" target="_blank" rel="noreferrer"><code>1.0.3</code></a></td></tr><tr><td>Fork UIX</td><td><a href="https://github.com/rockbaer2007/NeoMorphix-UIX/tree/experiment/uix-theme-variant" target="_blank" rel="noreferrer">rockbaer2007/NeoMorphix-UIX</a></td></tr><tr><td>Licence</td><td>selon le fichier README : MIT</td></tr><tr><td>Catégorie</td><td>Tableau de bord HA -&gt; Thèmes</td></tr></tbody></table><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation {#installation}&quot;">​</a></h2><p>NeoMorphix UIX est basé sur NeuMorphix et est conçu pour être utilisé comme thème dans HACS.</p><p><a href="https://my.home-assistant.io/redirect/hacs_repository/?owner=rockbaer2007&amp;repository=NeoMorphix-UIX&amp;category=theme" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/hacs_repository.svg" alt="Ouvrir NeoMorphix UIX dans HACS"></a></p><ol><li>Installez HACS, si ce n&#39;est pas déjà fait.</li><li>Installez <a href="https://uix.lf.technology/quick-start/" target="_blank" rel="noopener noreferrer">UIX</a>.</li><li>Installez le fork NeoMorphix-UIX en tant que thème via HACS.</li><li>Redémarrez Home Assistant.</li><li>Sélectionnez une variante de NeoMorphix-UIX dans le profil utilisateur ou dans les paramètres du tableau de bord.</li></ol><p>L&#39;intégration des thèmes doit être activée dans Home Assistant :</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  themes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!include_dir_merge_named</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> themes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>La version originale de NeoMorphix utilise <code>card-mod</code>. Pour NeoMorphix UIX, c&#39;est <code>UIX</code> qui est requis à la place.</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  themes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!include_dir_merge_named</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> themes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="varianten" tabindex="-1">Variantes <a class="header-anchor" href="#varianten" aria-label="Permalink to &quot;Variantes {#varianten}&quot;">​</a></h2><p>Le projet original fournit deux fichiers de thème :</p><ul><li><code>themes/neumorphix.yaml</code></li><li><code>themes/neumorphix-inset.yaml</code></li></ul><p>Ils contiennent six variantes de thème :</p><ul><li><code>neumorphix-light</code></li><li><code>neumorphix-dark</code></li><li><code>neumorphix-claude</code></li><li><code>neumorphix-light-inset</code></li><li><code>neumorphix-dark-inset</code></li><li><code>neumorphix-claude-inset</code></li></ul><p><code>Raised</code> donne l&#39;impression d&#39;une surface en relief (surélevée). <code>Inset</code> donne plutôt l&#39;impression d&#39;être enfoncée ou incrustée dans la surface.</p><h2 id="uix-variante" tabindex="-1">Variante UIX <a class="header-anchor" href="#uix-variante" aria-label="Permalink to &quot;Variante UIX {#uix-variante}&quot;">​</a></h2><p>Une branche complémentaire a été créée pour UIX ; elle ne remplace pas les fichiers <code>card-mod</code> originaux, mais ajoute des fichiers de thème UIX supplémentaires :</p><ul><li><a href="https://github.com/rockbaer2007/NeoMorphix-UIX/tree/experiment/uix-theme-variant" target="_blank" rel="noreferrer">Branche UIX dans le fork</a></li><li><a href="https://github.com/yakidd/NeumorphixHome/pull/4" target="_blank" rel="noreferrer">Pull Request vers le projet original</a></li></ul><p>La branche UIX ajoute :</p><ul><li><code>themes/NeoMorphix UIX.yaml</code></li><li><code>themes/NeoMorphix UIX Inset.yaml</code></li></ul><p>Les noms des thèmes supplémentaires sont :</p><ul><li><code>NeoMorphix UIX Light</code></li><li><code>NeoMorphix UIX Dark</code></li><li><code>NeoMorphix UIX Claude</code></li><li><code>NeoMorphix UIX Light Inset</code></li><li><code>NeoMorphix UIX Dark Inset</code></li><li><code>NeoMorphix UIX Claude Inset</code></li></ul><p>Sur le plan technique, les fichiers supplémentaires ont été associés à des clés de thème UIX :</p><ul><li><code>card-mod-theme</code> -&gt; <code>uix-theme</code></li><li><code>card-mod-root-yaml</code> -&gt; <code>uix-root-yaml</code></li><li><code>card-mod-sidebar-yaml</code> -&gt; <code>uix-drawer-yaml</code></li></ul><h2 id="hinweise" tabindex="-1">Remarques <a class="header-anchor" href="#hinweise" aria-label="Permalink to &quot;Remarques {#hinweise}&quot;">​</a></h2><ul><li>Le projet original indique la licence MIT dans son fichier README, mais ne contient pas de fichier <code>LICENSE</code> distinct dans le dépôt.</li><li>La variante UIX est conçue comme un complément. Les fichiers <code>card-mod</code> existants demeurent inchangés. - Avec les variantes « Inset », la page de configuration principale de Home Assistant peut se comporter différemment, car cette interface est rendue d&#39;une manière distincte des tableaux de bord (dashboards) classiques.</li></ul>`,30)])])}const m=i(s,[["render",o]]);export{u as __pageData,m as default};
